functions._adeEsc:
function _adeEsc(s) {
  return window._ebEsc ? window._ebEsc(s) : String(s == null ? "" : s)
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
}

functions._adeLoad:
function _adeLoad(storeName) {
  if (!window.eli || !window.eli.storage || typeof window.eli.storage.getAll !== "function") {
    return Promise.resolve([]);
  }
  return window.eli.storage.getAll(storeName).then(function (rows) {
    return (rows || []).filter(function (r) {
      return r && typeof r === "object" && (!r.id || String(r.id).charAt(0) !== "_");
    });
  }).catch(function () { return []; });
}

functions._adeSaveRow:
function _adeSaveRow(storeName, row) {
  if (!window.eli || !window.eli.storage || typeof window.eli.storage.put !== "function") {
    return Promise.reject(new Error("eli.storage unavailable"));
  }
  return window.eli.storage.put(storeName, row);
}

functions._adeDeleteRow:
function _adeDeleteRow(storeName, id) {
  if (!window.eli || !window.eli.storage || typeof window.eli.storage.delete !== "function") {
    return Promise.reject(new Error("eli.storage unavailable"));
  }
  return window.eli.storage.delete(storeName, id);
}

// Map tab → IDB store + library publisher manifest id (shown in intro).

functions._adeStoreFor:
function _adeStoreFor(tabId) {
  if (tabId === "agreement_types") return "agreement_types";
  if (tabId === "requesters")      return "requesters";
  return "prompts";
}

// Per-row renderers — return HTML strings for the list, wired by
// _adeWireRowHandlers after innerHTML. Each row's data-ade-id is the
// row's IDB primary key.

functions._adeRenderPromptRow:
function _adeRenderPromptRow(row) {
  return (
    '<div class="_ade_card" data-ade-id="' + _adeEsc(row.id) + '">' +
      '<div class="_ade_card_head">' +
        '<div>' +
          '<div class="_ade_card_id">' + _adeEsc(row.id) + '</div>' +
          '<div class="_ade_card_meta">' + ((row.text || "").length) + ' chars</div>' +
        '</div>' +
        '<div class="_ade_card_actions">' +
          '<button class="_ade_btn _ade_btn_save ade-save" data-ade-store="prompts" data-ade-id="' + _adeEsc(row.id) + '">💾 Save</button>' +
          '<button class="_ade_btn _ade_btn_del ade-del" data-ade-store="prompts" data-ade-id="' + _adeEsc(row.id) + '">🗑 Delete</button>' +
        '</div>' +
      '</div>' +
      '<div class="_ade_card_body">' +
        '<textarea class="_ade_textarea ade-text" data-ade-id="' + _adeEsc(row.id) + '">' + _adeEsc(row.text || "") + '</textarea>' +
      '</div>' +
    '</div>'
  );
}

// 2026-05-16: agreement_types + requesters render as compact SINGLE-row
// inline-editing strips for long-list scanability. Drops the card head +
// stacked labels (placeholders carry the meaning, columns are obvious).
// Prompts keep their card layout below — they need vertical textarea room.

functions._adeRenderAgreementRow:
function _adeRenderAgreementRow(row) {
  var aliases = Array.isArray(row.aliases) ? row.aliases : [];
  return (
    '<div class="_ade_row" data-ade-id="' + _adeEsc(row.id) + '">' +
      '<input type="text" class="_ade_input ade-at-label" data-ade-id="' + _adeEsc(row.id) + '" value="' + _adeEsc(row.label || "") + '" placeholder="Label" style="flex:1 1 30%; min-width:120px;">' +
      '<input type="text" class="_ade_input _ade_input_mono ade-at-aliases" data-ade-id="' + _adeEsc(row.id) + '" value="' + _adeEsc(aliases.join(", ")) + '" placeholder="aliases, comma, separated" style="flex:2 1 50%; min-width:160px;">' +
      '<div class="_ade_row_actions">' +
        '<button class="_ade_btn _ade_btn_save ade-save" data-ade-store="agreement_types" data-ade-id="' + _adeEsc(row.id) + '" title="Save">💾</button>' +
        '<button class="_ade_btn _ade_btn_del ade-del" data-ade-store="agreement_types" data-ade-id="' + _adeEsc(row.id) + '" title="Delete">🗑</button>' +
      '</div>' +
    '</div>'
  );
}

functions._adeRenderRequesterRow:
function _adeRenderRequesterRow(row) {
  return (
    '<div class="_ade_row" data-ade-id="' + _adeEsc(row.id) + '">' +
      '<input type="text" class="_ade_input ade-req-name" data-ade-id="' + _adeEsc(row.id) + '" value="' + _adeEsc(row.name || "") + '" placeholder="Name (e.g. Jane Doe)" style="flex:1 1 40%; min-width:140px;">' +
      '<input type="email" class="_ade_input _ade_input_mono ade-req-email" data-ade-id="' + _adeEsc(row.id) + '" value="' + _adeEsc(row.email || "") + '" placeholder="jane@example.com" style="flex:1 1 40%; min-width:160px;">' +
      '<div class="_ade_row_actions">' +
        '<button class="_ade_btn _ade_btn_save ade-save" data-ade-store="requesters" data-ade-id="' + _adeEsc(row.id) + '" title="Save">💾</button>' +
        '<button class="_ade_btn _ade_btn_del ade-del" data-ade-store="requesters" data-ade-id="' + _adeEsc(row.id) + '" title="Delete">🗑</button>' +
      '</div>' +
    '</div>'
  );
}

functions._adeWireRowHandlers:
function _adeWireRowHandlers(rootEl) {
  // Save handler — pulls latest field values, merges into existing row
  // (preserves unknown fields), writes to IDB.
  rootEl.querySelectorAll(".ade-save").forEach(function (btn) {
    btn.onclick = function () {
      var store = btn.getAttribute("data-ade-store");
      var id = btn.getAttribute("data-ade-id");
      // Accept either layout: prompts still use ._ade_card (textarea body
      // needs vertical room); agreement_types + requesters use the new
      // compact ._ade_row.
      var rowEl = btn.closest("._ade_row") || btn.closest("._ade_card");
      if (!rowEl) return;
      btn.disabled = true;
      var origText = btn.textContent;
      btn.textContent = "⏳";
      window.eli.storage.get(store, id).then(function (existing) {
        var row = existing && typeof existing === "object" ? Object.assign({}, existing) : { id: id };
        if (store === "prompts") {
          var ta = rowEl.querySelector(".ade-text");
          row.text = ta ? ta.value : "";
        } else if (store === "agreement_types") {
          var lab = rowEl.querySelector(".ade-at-label");
          var ali = rowEl.querySelector(".ade-at-aliases");
          row.label = lab ? lab.value.trim() : "";
          row.aliases = (ali ? ali.value : "").split(",")
            .map(function (a) { return a.trim(); })
            .filter(Boolean);
        } else if (store === "requesters") {
          var nm = rowEl.querySelector(".ade-req-name");
          var em = rowEl.querySelector(".ade-req-email");
          row.name = nm ? nm.value.trim() : "";
          row.email = em ? em.value.trim() : "";
        }
        return _adeSaveRow(store, row);
      }).then(function () {
        btn.textContent = "✓";
        btn.classList.add("_ade_btn_ok");
        if (typeof showToast === "function") showToast("Saved " + id, "ok");
        setTimeout(function () {
          btn.textContent = origText;
          btn.classList.remove("_ade_btn_ok");
          btn.disabled = false;
        }, 1200);
      }).catch(function (err) {
        btn.textContent = "❌";
        if (typeof showToast === "function") showToast("Save failed: " + (err && err.message || "unknown"), "err");
        setTimeout(function () { btn.textContent = origText; btn.disabled = false; }, 2000);
      });
    };
  });

  // Delete handler — confirms via eli.ui.confirm, removes from IDB + DOM.
  rootEl.querySelectorAll(".ade-del").forEach(function (btn) {
    btn.onclick = function () {
      var store = btn.getAttribute("data-ade-store");
      var id = btn.getAttribute("data-ade-id");
      if (!window.eli.ui || typeof window.eli.ui.confirm !== "function") return;
      window.eli.ui.confirm({
        variant: "danger", icon: "🗑",
        title: "Delete " + id + "?",
        message: "Removes the row from your local IDB. To remove it from all users' installs, push the section via Admin Library Publisher afterward.",
        confirmLabel: "Delete", cancelLabel: "Cancel",
      }).then(function (ok) {
        if (!ok) return;
        return _adeDeleteRow(store, id).then(function () {
          // Accept either layout: prompts still use ._ade_card, compact
          // rows use ._ade_row.
          var row = btn.closest("._ade_row") || btn.closest("._ade_card");
          if (row && row.parentNode) row.parentNode.removeChild(row);
          if (typeof showToast === "function") showToast("Deleted " + id, "info");
          // Refresh row count.
          var countEl = document.getElementById("adeCount");
          if (countEl) {
            var rowsLeft = rootEl.querySelectorAll("._ade_row, ._ade_card").length;
            countEl.innerHTML = "<strong>" + rowsLeft + "</strong> row" + (rowsLeft === 1 ? "" : "s");
          }
        }).catch(function (err) {
          if (typeof showToast === "function") showToast("Delete failed: " + (err && err.message || "unknown"), "err");
        });
      });
    };
  });
}

functions._adeRenderTab:
function _adeRenderTab(listEl, tabId, filterStr) {
  var store = _adeStoreFor(tabId);
  var renderRow = tabId === "agreement_types" ? _adeRenderAgreementRow
                : tabId === "requesters"      ? _adeRenderRequesterRow
                : _adeRenderPromptRow;
  listEl.innerHTML = '<div class="_ade_loading"><span class="_ade_loading_spinner"></span>Loading rows from <code>' + _adeEsc(store) + '</code>…</div>';
  return _adeLoad(store).then(function (rows) {
    // Reserved internal rows (id/key starts with "_", e.g. the
    // agreement_types "_meta" row) are kernel metadata — NOT user-
    // editable or deletable. Drop them before anything else so they
    // never render a card. Per CLAUDE.md, list-style consumers skip
    // leading-underscore ids.
    var editable = rows.filter(function (r) {
      return r && String((r.id != null ? r.id : (r.key != null ? r.key : r.stat_id)) || "").charAt(0) !== "_";
    });
    var f = String(filterStr || "").trim().toLowerCase();
    var visible = editable.filter(function (r) {
      if (!f) return true;
      var hay = JSON.stringify(r).toLowerCase();
      return hay.indexOf(f) !== -1;
    });
    var countEl = document.getElementById("adeCount");
    if (countEl) {
      countEl.innerHTML = "<strong>" + visible.length + "</strong> row" + (visible.length === 1 ? "" : "s") +
        (editable.length !== visible.length ? " (of " + editable.length + ")" : "");
    }
    if (!visible.length) {
      var icon = tabId === "agreement_types" ? "📋"
              : tabId === "requesters"      ? "👥"
              : "📝";
      listEl.innerHTML = '<div class="_ade_empty">' +
          '<div class="_ade_empty_icon">' + icon + '</div>' +
          '<div class="_ade_empty_title">' + (f ? "No matches" : "No rows in this store") + '</div>' +
          '<div class="_ade_empty_sub">' +
            (f ? "Nothing matched the filter — try a shorter search."
               : "Click ＋ ADD to create your first row.") +
          '</div>' +
        '</div>';
      return;
    }
    listEl.innerHTML = visible.map(renderRow).join("");
    _adeWireRowHandlers(listEl);
  });
}

functions._adeNewRowPrompt:
function _adeNewRowPrompt(tabId, listEl) {
  if (!window.eli.ui || typeof window.eli.ui.prompt !== "function") return;
  var promptLabel, placeholder;
  if (tabId === "prompts") {
    promptLabel = "New prompt id";
    placeholder = "e.g. clauseRevise";
  } else if (tabId === "agreement_types") {
    promptLabel = "New agreement-type id";
    placeholder = "e.g. Master Services Agreement";
  } else {
    promptLabel = "New requester name";
    placeholder = "e.g. Jane Doe";
  }
  window.eli.ui.prompt({
    title: "Add row",
    message: promptLabel + " (must be unique):",
    placeholder: placeholder,
    confirmLabel: "Add", cancelLabel: "Cancel",
  }).then(function (id) {
    if (!id || !id.trim()) return;
    id = id.trim();
    var store = _adeStoreFor(tabId);
    return window.eli.storage.get(store, id).then(function (existing) {
      if (existing) {
        if (typeof showToast === "function") showToast("'" + id + "' already exists", "warn");
        return;
      }
      var row;
      if (tabId === "prompts") {
        row = { id: id, text: "" };
      } else if (tabId === "agreement_types") {
        row = { id: id, label: id, aliases: [] };
      } else {
        row = { id: id, name: id, email: "" };
      }
      return _adeSaveRow(store, row).then(function () {
        if (typeof showToast === "function") showToast("Added '" + id + "'", "ok");
        var searchEl = document.getElementById("adeSearch");
        return _adeRenderTab(listEl, tabId, searchEl ? searchEl.value : "");
      });
    });
  });
}

functions.showAdminDataEditor:
function showAdminDataEditor() {
  var out = window.eli.ui.claimOutput();
  if (!out) return;
  out.classList.add("eli-view-enter");

  var root = document.createElement("div");
  root.className = "_ade_root";

  // Premium header — navy gradient + gold underline + eyebrow.
  var header = document.createElement("div");
  header.className = "_ade_header";
  header.innerHTML =
    '<div class="_ade_header_eyebrow">ADMIN — RESTRICTED</div>' +
    '<div class="_ade_header_title">📝 Data Editor</div>' +
    '<div class="_ade_header_sub">Edit AI prompts, agreement types, and requesters. Saves go to your local IDB — push via Library Publisher to roll out.</div>';
  root.appendChild(header);

  // Intro line — short, points to publisher.
  var intro = document.createElement("div");
  intro.className = "_ade_intro";
  intro.innerHTML =
    '<b>Editing flow:</b> change values here → save → switch to ' +
    '<code>Admin Library Publisher</code> → check the matching section ' +
    '(<code>__data_prompts</code>, <code>__data_agreement_types</code>, or ' +
    '<code>__data_requesters_proprietary</code>) → push.';
  root.appendChild(intro);

  // Tabs + Add button row.
  var toolbar = document.createElement("div");
  toolbar.className = "_ade_toolbar";
  toolbar.innerHTML =
    '<div class="_ade_tabs">' +
      '<button class="_ade_tab _ade_tab_active" data-ade-tab="prompts">📝 AI Prompts</button>' +
      '<button class="_ade_tab" data-ade-tab="agreement_types">📋 Agreement Types</button>' +
      '<button class="_ade_tab" data-ade-tab="requesters">👥 Requesters</button>' +
    '</div>' +
    '<button class="_ade_addbtn" id="adeAddBtn">＋ Add Row</button>';
  root.appendChild(toolbar);

  // Search.
  var searchWrap = document.createElement("div");
  searchWrap.className = "_ade_search_wrap";
  searchWrap.innerHTML =
    '<span class="_ade_search_icon">🔍</span>' +
    '<input type="text" id="adeSearch" class="_ade_search" placeholder="Filter rows…">';
  root.appendChild(searchWrap);

  // Row count.
  var count = document.createElement("div");
  count.id = "adeCount";
  count.className = "_ade_count";
  count.innerHTML = "<strong>0</strong> rows";
  root.appendChild(count);

  // List container.
  var listEl = document.createElement("div");
  listEl.id = "adeList";
  listEl.className = "_ade_list";
  root.appendChild(listEl);

  out.appendChild(root);

  var currentTab = "prompts";
  function _setTab(tab) {
    currentTab = tab;
    root.querySelectorAll("._ade_tab").forEach(function (b) {
      if (b.getAttribute("data-ade-tab") === tab) b.classList.add("_ade_tab_active");
      else b.classList.remove("_ade_tab_active");
    });
    var searchEl = document.getElementById("adeSearch");
    _adeRenderTab(listEl, tab, searchEl ? searchEl.value : "");
  }

  root.querySelectorAll("._ade_tab").forEach(function (b) {
    b.onclick = function () { _setTab(b.getAttribute("data-ade-tab")); };
  });
  document.getElementById("adeAddBtn").onclick = function () { _adeNewRowPrompt(currentTab, listEl); };

  // Debounced search.
  var searchTimer = null;
  document.getElementById("adeSearch").oninput = function () {
    if (searchTimer) clearTimeout(searchTimer);
    var val = this.value;
    searchTimer = setTimeout(function () {
      _adeRenderTab(listEl, currentTab, val);
    }, 200);
  };

  _setTab("prompts");
}

jsonTools.init:
function init(eli) {
  if (!eli || !eli.tools) return;

  function _show() {
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedAdminDataEditor"); } catch (e) {}
    try { if (eli.fsm && eli.fsm.getCurrent && eli.fsm.getCurrent() === "idle") eli.fsm.transition("scanning"); } catch (e) {}
    if (typeof window.showAdminDataEditor !== "function") {
      eli.log.event("tool", "admin_data_editor_fn_missing", {});
      if (typeof showToast === "function") showToast("Admin Data Editor failed to load", "err");
      return;
    }
    try { window.showAdminDataEditor(); }
    catch (e) {
      eli.log.event("tool", "admin_data_editor_failed", { msg: e && e.message });
      if (typeof showToast === "function") showToast("Open failed: " + (e.message || "unknown"), "err");
    }
  }

  // HTML escape helper, inlined (consistent with admin_library_publisher).
  if (typeof window._ebEsc !== "function") {
    window._ebEsc = function (s) {
      return String(s == null ? "" : s)
        .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
    };
  }

  eli.register({
    tile: { app_admin_data_editor: _show },
    admin_data_editor: { open: _show },
  });

  eli.log.event("tool", "admin_data_editor_initialized", {});
}

