  letter-spacing: 1.4px;
  text-transform: uppercase;
  color: #c9a227;
  margin-bottom: 4px;
}
._ade_header_title {
  font: 800 22px/1.1 "Book Antiqua", Georgia, serif;
  margin: 0;
}
._ade_header_sub {
  font-size: 11px;
  color: rgba(255, 255, 255, 0.7);
  margin-top: 4px;
  line-height: 1.4;
