  display: flex;
  gap: 4px;
  flex: 0 0 auto;
  margin-left: auto; /* pin to the right edge regardless of input widths */
}
._ade_row_actions ._ade_btn {
  padding: 6px 9px;
}

._ade_card_head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 10px 14px;
  background: linear-gradient(180deg, #fcfcfd, #f8fafc);
  border-bottom: 1px solid #f1f5f9;
}
._ade_card_id {
  font: 800 13px/1.3 ui-monospace, Consolas, monospace;
  color: #0f172a;
}
._ade_card_meta {
  font-size: 10px;
  font-weight: 600;
  color: #94a3b8;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  margin-top: 3px;
}
._ade_card_actions {
  display: flex;
  gap: 6px;
}

._ade_btn {
  padding: 6px 11px;
  font: 800 9px/1 Inter, sans-serif;
  letter-spacing: 0.5px;
  text-transform: uppercase;
  cursor: pointer;
  border: none;
  transition: filter 0.15s ease, background 0.15s ease;
  display: flex;
  align-items: center;
  gap: 4px;
}
._ade_btn:disabled { opacity: 0.55; cursor: wait; }
._ade_btn_save {
  background: #16a34a;
  color: #fff;
}
._ade_btn_save:hover:not(:disabled) { background: #15803d; }
._ade_btn_save._ade_btn_ok { background: #15803d; }
._ade_btn_del {
  background: #fff;
  color: #b91c1c;
  border: 1px solid #fca5a5;
}
._ade_btn_del:hover { background: #fef2f2; }

._ade_card_body {
  padding: 12px 14px;
}

._ade_field_label {
  font: 800 10.5px/1 Inter, sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: #64748b;
  margin-bottom: 6px;
}

._ade_input {
  width: 100%;
  padding: 9px 11px;
  font-size: 13px;
  font-family: Inter, "Segoe UI", system-ui, sans-serif;
  border: 1px solid #cbd5e1;
  outline: none;
  background: #fff;
  color: #0f172a;
  box-sizing: border-box;
  transition: border-color 0.15s ease;
}
._ade_input:focus { border-color: #1565c0; }
._ade_input_mono { font-family: ui-monospace, Consolas, monospace; }

._ade_textarea {
  width: 100%;
  min-height: 170px;
  padding: 12px 14px;
  /* Prompt/agreement text is PROSE — read it in Data Hub's body font at
     a comfortable size, not 11px monospace. */
  font-size: 13.5px;
  font-family: Inter, "Segoe UI", system-ui, sans-serif;
  line-height: 1.6;
  border: 1px solid #cbd5e1;
  outline: none;
  resize: vertical;
  background: #fff;
  color: #0f172a;
  box-sizing: border-box;
  transition: border-color 0.15s ease;
}
._ade_textarea:focus { border-color: #1565c0; }

._ade_field_grid_2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}
._ade_field_grid_label_value {
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: 10px;
  margin-top: 6px;
}

._ade_empty {
  padding: 50px 20px;
  text-align: center;
  color: #94a3b8;
  background: #fff;
  border: 1px dashed #e2e8f0;
}
._ade_empty_icon { font-size: 36px; margin-bottom: 8px; opacity: 0.5; }
._ade_empty_title { font-size: 13px; font-weight: 700; color: #475569; margin-bottom: 4px; }
._ade_empty_sub { font-size: 11px; }

._ade_loading {
  padding: 50px 20px;
  text-align: center;
  font-size: 12px;
  color: #94a3b8;
}
._ade_loading_spinner {
  display: inline-block;
  width: 16px; height: 16px;
  border: 2px solid #e2e8f0;
  border-top-color: #1565c0;
  border-radius: 50%;
  animation: _ade_spin 0.8s linear infinite;
  margin-right: 8px;
  vertical-align: middle;
}
@keyframes _ade_spin { to { transform: rotate(360deg); } }

._ade_toast_inline {
  display: inline-block;
  padding: 2px 8px;
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.4px;
  background: #dcfce7;
  color: #166534;
  margin-left: 8px;
}
